BEGIN
 SELECT jsonb_build_object(
 'rules',(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(x) ORDER BY codigo)::text,'[]'),'UTF8')),'hex') FROM lf_ops.nucleo_reglas x),
 'versions',(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(x) ORDER BY regla,version)::text,'[]'),'UTF8')),'hex') FROM lf_ops.nucleo_regla_versiones x),
 'hashes',(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_array(regla,version,lf_ops.nucleo_hash_paquete_v1(regla,version)) ORDER BY regla,version)::text,'[]'),'UTF8')),'hex') FROM lf_ops.nucleo_regla_versiones),
 'coverage',(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(x) ORDER BY legacy_id,nucleo_codigo,version_nucleo)::text,'[]'),'UTF8')),'hex') FROM lf_ops.lf_nucleo_cobertura_legada x),
 'applications',(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(x) ORDER BY regla,nodo)::text,'[]'),'UTF8')),'hex') FROM lf_ops.nucleo_aplicaciones x),
 'tests',(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(x) ORDER BY regla,version,n)::text,'[]'),'UTF8')),'hex') FROM lf_ops.nucleo_regla_pruebas x)
 ) INTO pre;
